w.mrp1:
⓶Ⓒⓐ wa=2 @ (Brot oder Gebäck) @ 
		{ a → NOM.SG(ABBR)}
		{ b → ACC.SG(ABBR)}
		{ c → NOM.PL(ABBR)}
		{ d → ACC.PL(ABBR)}
		{ e → GEN.SG(ABBR)}
		{ f → GEN.PL(ABBR)}
		{ g → D/L.SG(ABBR)}
		{ h → D/L.PL(ABBR)}
		{ i → ALL(ABBR)}
		{ j → ABL(ABBR)}
		{ k → INS(ABBR)}
		{ l → VOC.SG(ABBR)}
		{ m → VOC.PL(ABBR)} @ 14.2.3  @ (NINDA) 
		   += at @ 
		{ R → PPRO.3SG.N.NOM}
		{ S → PPRO.3SG.N.ACC}
		{ T → PPRO.3PL.C.NOM}
		{ U → PPRO.3PL.N.NOM}
		{ V → PPRO.3PL.N.ACC} @

